import glob,re
G="../../ressources/glossaire.md"
B={
"S01":("[cours S01](01-cours.md), sections 1 à 6 ; l'[aide-mémoire](03-aide-memoire.md).","carte mère, bus, mémoire vive, HDD/SSD, BIOS/UEFI, pilote.","un poste de récupération **débranché** et les outils fournis par l'enseignant (voir les Contraintes). Tu n'as rien à réparer : tu observes, tu nommes, tu notes."),
"S02":("[cours S02](01-cours.md), sections 1 à 5 ; l'[aide-mémoire](03-aide-memoire.md).","bit, octet, débit, PowerShell, invite de commandes.","un poste Windows et la fiche d'identité du poste à remplir. Les conversions se font **à la main**, avec la méthode du cours."),
"S03":("[cours S03](01-cours.md), sections 1 à 4 et 6 ; l'[aide-mémoire](03-aide-memoire.md).","cœur, fréquence, benchmark, RAID 0/1/5, ECC.","le catalogue fourni dans le dossier `tp/`. La partie E (NUMA) est **facultative**."),
"S04":("[cours S04](01-cours.md), sections 1 à 8 ; l'[aide-mémoire](03-aide-memoire.md).","noyau, BIOS, UEFI, MBR, GPT, TPM, UAC.","un poste Windows réel. Tu **observes sans rien modifier**."),
"S05":("[cours S05](01-cours.md), sections 1 à 6 ; l'[aide-mémoire](03-aide-memoire.md).","noyau, distribution, logiciel libre, GPL.","la grille de choix fournie. Les sources à consulter sont indiquées dans chaque partie ; note toujours **d'où vient** une information."),
"S06":("[cours S06](01-cours.md), sections 1 à 5 ; l'[aide-mémoire](03-aide-memoire.md).","machine virtuelle, hôte, invité, hyperviseur, fichier ISO.","VirtualBox installé et de la place sur le disque indiqué par l'enseignant. Les parties A à E se font en binôme, la partie F **seul**."),
"S07":("[cours S07](01-cours.md), sections 1 à 4 ; la fiche [minimum réseau](../../ressources/minimum-reseau.md) ; l'[aide-mémoire](03-aide-memoire.md).","snapshot, Guest Additions, adresse IP, DHCP, NAT, ping.","les VM Windows et Kali déjà installées. Les notions de réseau **seront revues en cours de réseau** : ici, tu les utilises sans les approfondir."),
"S08":("[cours S08](01-cours.md), sections 1 à 8 ; l'[aide-mémoire](03-aide-memoire.md).","terminal, prompt, chemin absolu et relatif, `sudo`, redirection, tube.","la VM Debian importée (partie A). **Session chargée, soyez concentrés** : avance partie par partie, les parties E et F sont facultatives."),
"S09":("[cours S09](01-cours.md), sections 1 à 5 ; l'[aide-mémoire](03-aide-memoire.md).","utilisateur, groupe, propriétaire, droits `rwx`, notation octale, lien symbolique.","la VM Debian de S08 avec l'arborescence `/var/partage/JackCelair` créée. Fais un **snapshot** avant de commencer."),
"S10":("[cours S10](01-cours.md), sections 1 à 6 ; l'[aide-mémoire](03-aide-memoire.md).","paquet, dépôt, script, variable, condition, boucle, code de retour.","la VM Debian avec `sudo`. La partie D se fait **seul** ; la partie E est facultative."),
"S11":("[cours S11](01-cours.md), sections 1 à 9 ; l'[aide-mémoire](03-aide-memoire.md) ; le rappel sur le port dans la fiche [minimum réseau](../../ressources/minimum-reseau.md).","conteneur, image, registre, port, variable d'environnement, volume.","un navigateur pour DockerLab (parties A à E) et une VM Debian pour la partie F. **Session chargée, soyez concentrés** : note tes commandes au fur et à mesure dans le journal."),
"S12":("[cours S12](01-cours.md), sections 1 à 7 ; l'[aide-mémoire](03-aide-memoire.md).","patrimoine, inventaire, agent, CMDB, donnée personnelle, RGPD.","l'accès à InfraLab (partie D) et le fichier d'inventaire fourni."),
"S13":("[cours S13](01-cours.md), sections 1 à 4 ; l'[aide-mémoire](03-aide-memoire.md).","agent, serveur web, base de données, GLPI, inventaire.","deux VM Debian et un snapshot de départ. Les commandes d'installation sont des **commandes de référence** : compare-les à la documentation officielle."),
"S14":("[cours S14](01-cours.md), sections 1 à 6 ; l'[aide-mémoire](03-aide-memoire.md).","GLPI, CMDB, élément de configuration (CI), entité, profil.","le serveur GLPI de S13 avec un poste inventorié (snapshot `GLPI installé`). Si un menu a un autre nom dans ta version, cherche la fonction et note le chemin réel."),
"S15":("[cours S15](01-cours.md), sections 1 à 7 ; l'[aide-mémoire](03-aide-memoire.md).","incident, problème, demande, changement, impact, urgence, priorité, SLA, ticket.","l'accès à InfraLab et au GLPI de S14. **Session chargée, soyez concentrés** : le tableau des quatre types de sollicitations (section 3 du cours) te sert de repère."),
"S16":("[cours S16](01-cours.md), sections 1 à 6 et la supervision ; l'[aide-mémoire](03-aide-memoire.md) ; les mots *ping*, *port*, *DNS* dans la fiche [minimum réseau](../../ressources/minimum-reseau.md).","ticket, priorité, diagnostic, base de connaissances, supervision.","l'accès à InfraLab et une VM pour la partie E (supervision)."),
"S17":("[cours S17](01-cours.md), sections 1 à 7 et la présence en ligne ; l'[aide-mémoire](03-aide-memoire.md).","service, SLA, OLA, disponibilité, incident majeur, RTO/RPO (cités, détaillés en S20).","l'accès à InfraLab et au GLPI de S14. **Session chargée, soyez concentrés.**"),
"S18":("[cours S18](01-cours.md), sections 1 à 5 ; la fiche [minimum réseau](../../ressources/minimum-reseau.md) ; l'[aide-mémoire](03-aide-memoire.md).","clonage, image maîtresse, PXE, DHCP, adresse IP.","un **réseau isolé** entre VM : ne branche **jamais** un serveur DHCP de TP sur le réseau du lycée."),
"S19":("[cours S19](01-cours.md), sections 1 à 9 ; l'[aide-mémoire](03-aide-memoire.md) ; le TP de S10.","script, variable, boucle, code de retour, cron, SSH, paire de clés, `systemctl` (commande qui démarre, arrête et interroge un service).","la VM Debian de S10 avec `sudo` et un snapshot. **Session chargée, soyez concentrés** : la partie C est facultative ; la partie G est marquée notion technique."),
"S20":("[cours S20](01-cours.md), sections 1 à 8 ; l'[aide-mémoire](03-aide-memoire.md).","sauvegarde, restauration, RPO, RTO, règle 3-2-1, empreinte, chiffrement, clé privée.","la VM de S13/S14 avec GLPI et sa base. Les commandes `gpg` sont à **chercher dans le manuel** avant d'être tapées."),
"S21":("les cours S11 à S20, tes comptes rendus et le [cours S21](01-cours.md), section 6 (vocabulaire de l'examen).","fiche de réalisation, portfolio, tableau de synthèse, entretien d'explicitation, recette.","tes journaux et preuves des séances précédentes. **Session chargée, soyez concentrés** : commence la partie B tout de suite, elle se termine à la maison."),
}
for f in sorted(glob.glob("docs/semestre-*/S*/02-tp.md")):
    s=f.split("/")[-2][:3]; rel,mots,prep=B[s]
    t=open(f,encoding="utf-8").read()
    if "À savoir avant de commencer" in t: continue
    blk=f"> [!NOTE] À savoir avant de commencer\n> - **À relire :** {rel}\n> - **Mots à connaître :** {mots} Tout est dans le [glossaire]({G}).\n> - **À préparer :** {prep}\n\n"
    m=re.search(r"^## ",t,re.M); assert m,f
    open(f,"w",encoding="utf-8").write(t[:m.start()]+blk+t[m.start():])
